# UARD (Untrapped Auto-Repair Diagnostic) ver 1.0.1 - TRUE BASELINE
# Canonical repair endpoint: 000-999 audit middleman.
$ErrorActionPreference='Stop'
$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.1';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Middleman='https://untrapped-update-middleman-000-999-production.up.railway.app';$ArtifactBase=$Middleman+'/v1/artifact/';$Report=Join-Path $Root 'repair-success-latest.txt';$BackupRoot=Join-Path $Root 'repair-backups';$log=New-Object 'System.Collections.Generic.List[string]';$changed=$false;$failed=$false;$unknown=$false;$CanonicalCache=@{};$sw=[Diagnostics.Stopwatch]::StartNew()
function Log([string]$m){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$m;Write-Host $x;[void]$log.Add($x)}
function HashBytes([byte[]]$b){$s=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($s.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Normalize([byte[]]$b,[string]$n,[string]$t){if($t -eq 'json'){return $b};$s=[Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF).Trim();if(-not $s.StartsWith('{')){return $b};try{$j=$s|ConvertFrom-Json -ErrorAction Stop}catch{return $b};$lang='';if($j.PSObject.Properties.Name -contains 'language'){$lang=[string]$j.language}elseif($j.PSObject.Properties.Name -contains 'lang'){$lang=[string]$j.lang};$explicit=$lang.ToLowerInvariant() -in @('powershell','powershell-script','powershellscript','ps1','pwsh');if(-not $explicit){return $b};foreach($k in @('powershell','script','source','code','content','text','body')){if($j.PSObject.Properties.Name -contains $k -and $j.$k -is [string]){return [Text.Encoding]::UTF8.GetBytes(([string]$j.$k).TrimEnd()+"`n")}};if($j.PSObject.Properties.Name -contains 'commands' -and $j.commands -is [array] -and @($j.commands|Where-Object{$_ -isnot [string]}).Count -eq 0){return [Text.Encoding]::UTF8.GetBytes((($j.commands -join "`n").TrimEnd()+"`n"))};return $b}
function RemoteBytes([string]$n,[string]$t){if($CanonicalCache.ContainsKey($n)){return $CanonicalCache[$n]};for($a=1;$a -le 5;$a++){try{Log ('FETCH '+$n+' attempt '+$a+'/5');$q=[Net.HttpWebRequest]::Create($ArtifactBase+$n+'?cb='+[DateTime]::UtcNow.Ticks);$q.Method='GET';$q.Timeout=30000;$q.ReadWriteTimeout=30000;$q.UserAgent='UARD/1.0.1';$r=$q.GetResponse();try{if($r.ContentLength -gt 8388608){throw 'canonical artifact exceeds 8 MiB limit'};$st=$r.GetResponseStream();$ms=New-Object IO.MemoryStream;$st.CopyTo($ms);$raw=$ms.ToArray()}finally{if($st){$st.Dispose()};$r.Dispose()};if($raw.Length -gt 8388608){throw 'canonical artifact exceeds 8 MiB limit'};$x=Normalize $raw $n $t;$CanonicalCache[$n]=$x;Log ('DOWNLOAD OK '+$n+' '+$x.Length+' bytes SHA256='+(HashBytes $x));return $x}catch{$c=0;try{$c=[int]$_.Exception.Response.StatusCode}catch{};if($c -in @(408,429) -or $c -ge 500){Log ('TRANSIENT FETCH ERROR '+$n+' HTTP '+$c+'; retrying')}else{Log ('CANONICAL FETCH ERROR '+$n+': '+$_.Exception.Message);break};Start-Sleep -Seconds ([Math]::Min($a,4))}};$script:unknown=$true;Log ('UNVERIFIED '+$n+' canonical source unavailable.');return $null}
function ValidPS([byte[]]$b,[string]$n){try{$s=[Text.Encoding]::UTF8.GetString($b);$null=[scriptblock]::Create($s);return $true}catch{Log ('SCRIPT VALIDATION FAILED '+$n+': '+$_.Exception.Message);return $false}}
function Backup([string]$p){if(Test-Path -LiteralPath $p){$d=Join-Path $BackupRoot (Get-Date -Format 'yyyyMMdd-HHmmssfff');New-Item -ItemType Directory -Path $d -Force|Out-Null;Copy-Item -LiteralPath $p -Destination (Join-Path $d (Split-Path $p -Leaf)) -Force;Log ('BACKUP '+$p)}}
function Install([string]$p,[byte[]]$b){$d=Split-Path -Parent $p;if(-not(Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$tmp=$p+'.uaudtmp-'+[Guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$b);Move-Item -LiteralPath $tmp -Destination $p -Force}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}}
function PolicyDiag{$l=Get-ExecutionPolicy -List|Out-String;Log ('EXECUTION POLICY '+(($l.Trim()-replace '\r?\n',' | ')));$mp=(Get-ExecutionPolicy -Scope MachinePolicy);$up=(Get-ExecutionPolicy -Scope UserPolicy);if($mp -ne 'Undefined' -or $up -ne 'Undefined'){Log 'GROUP POLICY EXECUTION POLICY DETECTED; -ExecutionPolicy Bypass cannot override MachinePolicy/UserPolicy.';$script:unknown=$true};$lm=$ExecutionContext.SessionState.LanguageMode;Log ('LANGUAGE MODE '+$lm);if($lm -ne 'FullLanguage'){Log 'APPLICATION CONTROL / CONSTRAINED LANGUAGE MAY RESTRICT SCRIPT OPERATIONS.';$script:unknown=$true};$zone=Get-Item -LiteralPath $PSCommandPath -Stream Zone.Identifier -ErrorAction SilentlyContinue;if($zone){Log 'ZONE.IDENTIFIER PRESENT ON UARD; attempting local unblock.';try{Unblock-File -LiteralPath $PSCommandPath -ErrorAction Stop;Log 'UNBLOCK OK'}catch{Log ('UNBLOCK FAILED: '+$_.Exception.Message);$script:unknown=$true}}}
Log ($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE');Log ('MIDDLEMAN '+$Middleman);Log 'Protected boundary: no Windows Firewall/WFP/DNS/routes/Hosts/proxy/VPN/adapter/override-policy changes.';PolicyDiag
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1');foreach($n in $core){$p=Join-Path $Root $n;$t=if($n -eq 'config.json'){'json'}else{'ps1'};$x=RemoteBytes ('ultra-mode/'+$n) $t;if($null -eq $x){continue};if($t -eq 'ps1' -and -not(ValidPS $x $n)){$script:failed=$true;continue};$cur=if(Test-Path -LiteralPath $p){[IO.File]::ReadAllBytes($p)}else{$null};if($null -eq $cur -or (HashBytes $cur) -ne (HashBytes $x)){Backup $p;Install $p $x;$script:changed=$true;Log ('REPAIRED '+$n)}else{Log ('CURRENT '+$n)}}
foreach($n in @('WinDivert.dll','WinDivert64.sys')){$f=Get-ChildItem -LiteralPath $Root -Filter $n -File -Recurse -ErrorAction SilentlyContinue|Select-Object -First 1;if($f){Log ('NATIVE OK '+$n)}else{Log ('NATIVE MISSING '+$n);$script:failed=$true}}
if(Test-Path -LiteralPath $Root){try{$probe=Join-Path $Root ('.uaud-write-test-'+[Guid]::NewGuid().ToString('N'));[IO.File]::WriteAllText($probe,'ok');Remove-Item $probe -Force;Log 'WRITE ACCESS OK'}catch{Log ('WRITE ACCESS FAILED: '+$_.Exception.Message);$script:failed=$true}}
$diagnosis='NO REPAIR REQUIRED';if($failed){$diagnosis='REPAIR INCOMPLETE'}elseif($unknown){$diagnosis='VERIFICATION INCOMPLETE'}elseif($changed){$diagnosis='REPAIR SUCCESS'};Log ('[DIAGNOSIS] '+$diagnosis);$sw.Stop();Log ('RUNTIME '+$sw.Elapsed.ToString());if($changed -or $failed -or $unknown){$reportText=@($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE','Run: '+(Get-Date),'Diagnosis: '+$diagnosis,'Middleman: '+$Middleman,'','Protected boundary unchanged.','',$log);$reportText|Set-Content -LiteralPath $Report -Encoding UTF8;try{Start-Process notepad.exe -ArgumentList @($Report)|Out-Null}catch{}};if($failed){exit 1};if($unknown){exit 2};exit 0
